import { describe, it, expect, vi, beforeEach, afterEach } from "vitest"
import { render, screen, cleanup, fireEvent } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import ThemeToggle from "./ThemeToggle.jsx"

function mockPrefersDark(dark) {
  window.matchMedia = vi.fn().mockImplementation((query) => ({
    matches: dark,
    media: query,
    onchange: null,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    dispatchEvent: () => false,
  }))
}

function resetDocument() {
  delete document.documentElement.dataset.theme
  localStorage.clear()
}

describe("ThemeToggle", () => {
  beforeEach(() => {
    resetDocument()
    mockPrefersDark(false)
  })

  afterEach(() => {
    cleanup()
    resetDocument()
    vi.restoreAllMocks()
  })

  it("renders a type=button with the 'Dark mode' label", () => {
    render(<ThemeToggle />)
    const button = screen.getByRole("button", { name: "Dark mode" })
    expect(button.tagName).toBe("BUTTON")
    expect(button.getAttribute("type")).toBe("button")
    expect(button.textContent).toBe("Dark mode")
  })

  describe("initial theme with no saved value", () => {
    it("uses light when the OS prefers light", () => {
      mockPrefersDark(false)
      render(<ThemeToggle />)
      expect(document.documentElement.dataset.theme).toBe("light")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("false")
    })

    it("uses dark when the OS prefers dark", () => {
      mockPrefersDark(true)
      render(<ThemeToggle />)
      expect(window.matchMedia).toHaveBeenCalledWith("(prefers-color-scheme: dark)")
      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("true")
    })
  })

  describe("saved value in localStorage", () => {
    it("uses saved 'light' even when the OS prefers dark", () => {
      mockPrefersDark(true)
      localStorage.setItem("theme", "light")
      render(<ThemeToggle />)
      expect(document.documentElement.dataset.theme).toBe("light")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("false")
    })

    it("uses saved 'dark' even when the OS prefers light", () => {
      mockPrefersDark(false)
      localStorage.setItem("theme", "dark")
      render(<ThemeToggle />)
      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("true")
    })

    it("ignores an unrecognized saved value and falls back to the OS preference", () => {
      mockPrefersDark(true)
      localStorage.setItem("theme", "purple")
      render(<ThemeToggle />)
      expect(document.documentElement.dataset.theme).toBe("dark")
    })
  })

  describe("click", () => {
    it("flips light to dark, updates the document and aria-pressed, and saves 'dark'", () => {
      mockPrefersDark(false)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      fireEvent.click(button)

      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(button.getAttribute("aria-pressed")).toBe("true")
      expect(localStorage.getItem("theme")).toBe("dark")
    })

    it("flips dark back to light and saves 'light'", () => {
      mockPrefersDark(true)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      fireEvent.click(button)

      expect(document.documentElement.dataset.theme).toBe("light")
      expect(button.getAttribute("aria-pressed")).toBe("false")
      expect(localStorage.getItem("theme")).toBe("light")
    })

    it("alternates correctly across multiple clicks", () => {
      mockPrefersDark(false)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      fireEvent.click(button)
      fireEvent.click(button)
      fireEvent.click(button)

      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(localStorage.getItem("theme")).toBe("dark")
    })
  })

  describe("keyboard", () => {
    it("Enter on the focused button toggles the theme", async () => {
      const user = userEvent.setup()
      mockPrefersDark(false)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      button.focus()
      await user.keyboard("{Enter}")

      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(localStorage.getItem("theme")).toBe("dark")
    })

    it("Space on the focused button toggles the theme", async () => {
      const user = userEvent.setup()
      mockPrefersDark(false)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      button.focus()
      await user.keyboard(" ")

      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(localStorage.getItem("theme")).toBe("dark")
    })
  })
})

