import { useLayoutEffect, useState } from "react"

const STORAGE_KEY = "theme"

function getInitialTheme() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (saved === "light" || saved === "dark") return saved
  } catch {
    // storage unavailable; fall back to the system preference
  }
  return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"
}

export default function ThemeToggle() {
  const [theme, setTheme] = useState(getInitialTheme)

  useLayoutEffect(() => {
    document.documentElement.dataset.theme = theme
  }, [theme])

  function toggle() {
    const next = theme === "dark" ? "light" : "dark"
    try {
      localStorage.setItem(STORAGE_KEY, next)
    } catch {
      // storage unavailable or full; keep the in-memory theme change
    }
    setTheme(next)
  }

  return (
    <button type="button" aria-pressed={theme === "dark"} onClick={toggle}>
      Dark mode
    </button>
  )
}

import ThemeToggle from "./ThemeToggle.jsx"

export default function Header({ count }) {
  return (
    <header className="header">
      <h1>Todos</h1>
      <div className="header-actions">
        <span>{count} left</span>
        <ThemeToggle />
      </div>
    </header>
  )
}

:root {
  --bg: #ffffff;
  --fg: #1d1d1f;
  --muted: #6e6e73;
  --accent: #2f6feb;
  --on-accent: #ffffff;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #1c1c1e;
  --fg: #f5f5f7;
  --muted: #98989d;
  --accent: #4d8dff;
  --on-accent: #1c1c1e;
}

body {
  margin: 0;
  font-family: system-ui, sans-serif;
  background: var(--bg);
  color: var(--fg);
}

.app { max-width: 480px; margin: 40px auto; padding: 0 16px; }
.header { display: flex; justify-content: space-between; align-items: baseline; }
.header-actions { display: flex; align-items: center; gap: 12px; }
form { display: flex; gap: 8px; margin: 16px 0; }
form input { flex: 1; padding: 8px; }
button { padding: 8px 12px; background: var(--accent); color: var(--on-accent); border: 0; border-radius: 4px; }
.list { list-style: none; padding: 0; }
.list li { display: flex; justify-content: space-between; padding: 8px 0; }
.list li.done label { text-decoration: line-through; color: var(--muted); }
.empty { color: var(--muted); }

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest"
import { render, screen, cleanup, fireEvent } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import ThemeToggle from "./ThemeToggle.jsx"

function mockPrefersDark(dark) {
  window.matchMedia = vi.fn().mockImplementation((query) => ({
    matches: dark,
    media: query,
    onchange: null,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    dispatchEvent: () => false,
  }))
}

function resetDocument() {
  delete document.documentElement.dataset.theme
  localStorage.clear()
}

describe("ThemeToggle", () => {
  beforeEach(() => {
    resetDocument()
    mockPrefersDark(false)
  })

  afterEach(() => {
    cleanup()
    resetDocument()
    vi.restoreAllMocks()
  })

  it("renders a type=button with the 'Dark mode' label", () => {
    render(<ThemeToggle />)
    const button = screen.getByRole("button", { name: "Dark mode" })
    expect(button.tagName).toBe("BUTTON")
    expect(button.getAttribute("type")).toBe("button")
    expect(button.textContent).toBe("Dark mode")
  })

  describe("initial theme with no saved value", () => {
    it("uses light when the OS prefers light", () => {
      mockPrefersDark(false)
      render(<ThemeToggle />)
      expect(document.documentElement.dataset.theme).toBe("light")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("false")
    })

    it("uses dark when the OS prefers dark", () => {
      mockPrefersDark(true)
      render(<ThemeToggle />)
      expect(window.matchMedia).toHaveBeenCalledWith("(prefers-color-scheme: dark)")
      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("true")
    })
  })

  describe("saved value in localStorage", () => {
    it("uses saved 'light' even when the OS prefers dark", () => {
      mockPrefersDark(true)
      localStorage.setItem("theme", "light")
      render(<ThemeToggle />)
      expect(document.documentElement.dataset.theme).toBe("light")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("false")
    })

    it("uses saved 'dark' even when the OS prefers light", () => {
      mockPrefersDark(false)
      localStorage.setItem("theme", "dark")
      render(<ThemeToggle />)
      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("true")
    })

    it("ignores an unrecognized saved value and falls back to the OS preference", () => {
      mockPrefersDark(true)
      localStorage.setItem("theme", "purple")
      render(<ThemeToggle />)
      expect(document.documentElement.dataset.theme).toBe("dark")
    })
  })

  describe("click", () => {
    it("flips light to dark, updates the document and aria-pressed, and saves 'dark'", () => {
      mockPrefersDark(false)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      fireEvent.click(button)

      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(button.getAttribute("aria-pressed")).toBe("true")
      expect(localStorage.getItem("theme")).toBe("dark")
    })

    it("flips dark back to light and saves 'light'", () => {
      mockPrefersDark(true)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      fireEvent.click(button)

      expect(document.documentElement.dataset.theme).toBe("light")
      expect(button.getAttribute("aria-pressed")).toBe("false")
      expect(localStorage.getItem("theme")).toBe("light")
    })

    it("alternates correctly across multiple clicks", () => {
      mockPrefersDark(false)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      fireEvent.click(button)
      fireEvent.click(button)
      fireEvent.click(button)

      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(localStorage.getItem("theme")).toBe("dark")
    })
  })

  describe("keyboard", () => {
    it("Enter on the focused button toggles the theme", async () => {
      const user = userEvent.setup()
      mockPrefersDark(false)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      button.focus()
      await user.keyboard("{Enter}")

      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(localStorage.getItem("theme")).toBe("dark")
    })

    it("Space on the focused button toggles the theme", async () => {
      const user = userEvent.setup()
      mockPrefersDark(false)
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      button.focus()
      await user.keyboard(" ")

      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(localStorage.getItem("theme")).toBe("dark")
    })
  })

  describe("when localStorage throws", () => {
    function storageError(name) {
      return new DOMException(`${name} denied`, "SecurityError")
    }

    it("getItem throws: still renders and falls back to light when the OS prefers light", () => {
      mockPrefersDark(false)
      const getSpy = vi.spyOn(Storage.prototype, "getItem").mockImplementation(() => {
        throw storageError("getItem")
      })

      render(<ThemeToggle />)

      expect(getSpy).toHaveBeenCalledWith("theme")
      const button = screen.getByRole("button", { name: "Dark mode" })
      expect(button.textContent).toBe("Dark mode")
      expect(document.documentElement.dataset.theme).toBe("light")
      expect(button.getAttribute("aria-pressed")).toBe("false")
    })

    it("getItem throws: falls back to dark when the OS prefers dark", () => {
      mockPrefersDark(true)
      vi.spyOn(Storage.prototype, "getItem").mockImplementation(() => {
        throw storageError("getItem")
      })

      render(<ThemeToggle />)

      expect(window.matchMedia).toHaveBeenCalledWith("(prefers-color-scheme: dark)")
      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(screen.getByRole("button", { name: "Dark mode" }).getAttribute("aria-pressed")).toBe("true")
    })

    it("setItem throws on click: click does not throw and the theme still flips", () => {
      mockPrefersDark(false)
      const setSpy = vi.spyOn(Storage.prototype, "setItem").mockImplementation(() => {
        throw storageError("setItem")
      })
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })
      expect(document.documentElement.dataset.theme).toBe("light")

      expect(() => fireEvent.click(button)).not.toThrow()

      expect(setSpy).toHaveBeenCalledWith("theme", "dark")
      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(button.getAttribute("aria-pressed")).toBe("true")
      expect(localStorage.getItem("theme")).toBeNull()
    })

    it("setItem throws on click: two clicks from dark return to dark, each attempt flips the theme", () => {
      mockPrefersDark(true)
      vi.spyOn(Storage.prototype, "setItem").mockImplementation(() => {
        throw storageError("setItem")
      })
      render(<ThemeToggle />)
      const button = screen.getByRole("button", { name: "Dark mode" })

      fireEvent.click(button)
      expect(document.documentElement.dataset.theme).toBe("light")
      expect(button.getAttribute("aria-pressed")).toBe("false")

      expect(() => fireEvent.click(button)).not.toThrow()
      expect(document.documentElement.dataset.theme).toBe("dark")
      expect(button.getAttribute("aria-pressed")).toBe("true")
    })
  })
})

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest"
import { render, screen, cleanup } from "@testing-library/react"
import Header from "./Header.jsx"

function mockPrefersDark(dark) {
  window.matchMedia = vi.fn().mockImplementation((query) => ({
    matches: dark,
    media: query,
    onchange: null,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    dispatchEvent: () => false,
  }))
}

describe("Header", () => {
  beforeEach(() => {
    delete document.documentElement.dataset.theme
    localStorage.clear()
    mockPrefersDark(false)
  })

  afterEach(() => {
    cleanup()
    delete document.documentElement.dataset.theme
    localStorage.clear()
    vi.restoreAllMocks()
  })

  it("renders the count alongside the theme toggle inside .header-actions", () => {
    const { container } = render(<Header count={3} />)

    expect(screen.getByText("3 left")).toBeTruthy()
    const actions = container.querySelector(".header-actions")
    expect(actions).not.toBeNull()
    expect(actions.textContent).toContain("3 left")
    expect(actions.querySelector("button")).not.toBeNull()
    expect(screen.getByRole("button", { name: "Dark mode" })).toBeTruthy()
  })
})

{
  "name": "todo-demo",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "test": "vitest run"
  },
  "dependencies": {
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@testing-library/react": "^16.0.0",
    "@vitejs/plugin-react": "^4.3.1",
    "jsdom": "^25.0.0",
    "vite": "^5.4.0",
    "vitest": "^2.1.0"
  }
}

import { defineConfig } from "vite"
import react from "@vitejs/plugin-react"

export default defineConfig({
  plugins: [react()],
  test: { environment: "jsdom" },
})

import { useState } from "react"
import Header from "./Header.jsx"
import TodoList from "./TodoList.jsx"

export default function App() {
  const [todos, setTodos] = useState([
    { id: 1, text: "Buy milk", done: false },
    { id: 2, text: "Write tests", done: true },
  ])
  const [text, setText] = useState("")

  function add(e) {
    e.preventDefault()
    if (!text.trim()) return
    setTodos([...todos, { id: Date.now(), text: text.trim(), done: false }])
    setText("")
  }

  function toggle(id) {
    setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)))
  }

  function remove(id) {
    setTodos(todos.filter((t) => t.id !== id))
  }

  return (
    <main className="app">
      <Header count={todos.filter((t) => !t.done).length} />
      <form onSubmit={add}>
        <input value={text} onChange={(e) => setText(e.target.value)} placeholder="What needs doing?" />
        <button type="submit">Add</button>
      </form>
      <TodoList todos={todos} onToggle={toggle} onRemove={remove} />
    </main>
  )
}

